import sys

def count_words(arr):
    count = 0
    in_word = False
    for ch in arr:
        if ch != ' ':
            if not in_word:
                count += 1
                in_word = True
        else:
            in_word = False
    return count

def main():
    data = sys.stdin.readline().rstrip('\n')
    print(count_words(data))

if __name__ == "__main__":
    main()
